window.TLL_STORIES=[{"name": "From Sequins to Sloths: Northern Brazil for the Chronically Curious", "slug": "northern-brazil-sequins-to-sloths", "country": "SALVADOR, BRAZIL", "pillar": "Stories From the Road", "mins": 6, "lede": "When you are seeking that spark of life, you chase it. Carnaval in Salvador with 2.5 million people, a desert that fills with water every year, and six days on the Rio Negro with pink dolphins and one sloth with somewher", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6abccf813c37a815d4c03dde_6abcce087012c0cb94fe18b3_brazil-hero-riverboats-at-sunset-rio-negro.jpeg"}, {"name": "I Drove Across Denmark to Watch a Million Birds Go to Bed", "slug": "sort-sol-black-sun-denmark", "country": "RUDBØL, DENMARK", "pillar": "Stories From the Road", "mins": 8, "lede": "A last-minute trip to the German border for Sort Sol, the marshland murmuration that only does the famous part when something tries to eat it. Plus the falcon that never showed, and the correct way to cross the Fyn bridg", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6aba3d42f18f65b8d06aea74_6aba3cbc0a48f32b1687edfc_sortsol-hero-murmuration-over-the-cars.jpeg"}, {"name": "La Paz, whale sharks, and a sea lion who chose chaos", "slug": "la-paz-mexico-whale-sharks", "country": "MEXICO", "pillar": "Stories From the Road", "mins": 3, "lede": "Wider than your sense of scale, moving with an ease that is almost funny once the initial shock wears off. Then the sea lions, who chose chaos.", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6aae867b7b616826932f4444_6a0e022469c0ce59398ce287_La%2520Paz%2520Mexico.jpeg"}, {"name": "Patagonia, measured in Camp Italianos", "slug": "patagonia-w-trek-christmas-new-year", "country": "CHILE AND ARGENTINA", "pillar": "Stories From the Road", "mins": 6, "lede": "Some people do vision boards. We did blisters. An accelerated W Trek over Christmas, a rainbow nobody deserved, and a New Year in the golden light at Estancia Bonanza.", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6a3e79b1f2ea14b30d7a5e0f_6a0e0225995b48deb53b96e8_Fitz%2520Roy.jpeg"}, {"name": "The annual retreat, or what happens when you put a Mangalitsa fillet and a switchback road in a blender", "slug": "montenegro-budva-switchback-roads", "country": "MONTENEGRO", "pillar": "Stories From the Road", "mins": 3, "lede": "Montenegro's roads are about to get a quiet word from Nepal, Austria and Croatia. Narrow, one-way as a suggestion, with semi-trucks reversing down mountains.", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6a0e027dbb2d090c01c473b4_6a0e02265e2392e5fc632431_Montenegro%2520coast.jpeg"}, {"name": "Ghana asked us to wear all white. We complied. Eventually.", "slug": "ghana-easter-everyone-wears-white", "country": "GHANA", "pillar": "Cultural Intelligence", "mins": 3, "lede": "Denmark had just thrown the coldest winter in 16 years at us, the map had a gap, and we had a few days. Then we landed in a country where everyone was wearing white except us.", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6a0e027dbb2d090c01c473b8_6a0e0224fb0e0ee3c092ec01_Ghana%2520kids.jpeg"}, {"name": "Fourteen days, twelve countries, one EV, and a gal who cannot be historically trusted to charge her own phone", "slug": "balkans-ev-road-trip-twelve-countries", "country": "BALKANS", "pillar": "Travel Logistics", "mins": 9, "lede": "Copenhagen to Kosovo and back in an EV, with one Samoyed operating in an advisory capacity and a back seat that ended up looking like a small artisan jam factory in transit.", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6aae867b7b616826932f4447_6a1183262f8a632aeff43aed_Bulgaria.jpeg"}, {"name": "Whiskey on 10,000-Year-Old Ice and Chasing the Impossible: The Antarctica Marathon", "slug": "antarctica-marathon", "country": "KING GEORGE ISLAND, ANTARCTICA", "pillar": "Stories From the Road", "mins": 12, "lede": "The honeymoon that became a four-year cancellation saga, and then the coldest, strangest, most beautiful race I have ever run. Four attempts, one pandemic, and an apartment marathon I recommend to nobody.", "img": "https://cdn.prod.website-files.com/6a0b29c6d081332e921900d8/6ab3d9bc5c183888afac103a_6ab3d9295c183888afabcab9_antarctica-hero-landing-in-the-sun.jpeg"}];
